      if (this.session.sheetId() === sheet) this.closed.emit(closed);
    } catch {
      if (this.session.sheetId() !== sheet) return;
      this.rowErrors.update((errors) => ({ ...errors, [period.id]: 'That period could not be closed.' }));
    }
  }

